import { ApiError } from '@/api/client';

export const AI_NOTE =
  'Generated by AI. Not checked by a person. Use your judgement, especially with meat, eggs and allergens.';

const GENERIC = 'Something went wrong. Please try again.';

const BY_CODE: Record<string, string> = {
  no_preferences: 'Set your food preferences first.',
  daily_limit: "You've used today's 10 AI recipes. More tomorrow.",
  ai_quota: 'The free AI limit is reached for now. Try again later.',
  ai_unavailable: "The AI service isn't responding. Try again in a minute.",
  ai_not_configured: "AI features aren't set up on this server.",
  generation_failed: "Couldn't make a safe new recipe from these. Try changing the ingredients.",
  invalid_photo: 'Use 1 to 3 photos (JPEG, up to 1 MB each).',
  scan_limit: "You've used today's 10 photo scans. More tomorrow.",
  scan_failed: "Couldn't read the photo. Try again or type your ingredients.",
  no_dish: "Couldn't find a dish in this post. Try a screenshot that shows the food or the recipe.",
  invalid_post: 'Add a caption (up to 2,200 characters) or 1 to 2 screenshots.',
};

/** Shown on the post tab in place of the scan's `invalid_photo` wording (at most 2 screenshots there). */
export const SCREENSHOT_INVALID = 'Use 1 or 2 screenshots (JPEG, up to 1 MB each).';

/** Shown when the browser can't decode a picked photo (for example HEIC in Chrome on Windows) or can't shrink it enough. */
export const PHOTO_UNREADABLE = "This photo type can't be opened here. Try a JPEG or take a new photo.";

/** The message to show for a failed AI call: the spec's text for its `code`, else the server's detail. */
export function aiErrorMessage(err: unknown): string {
  if (!(err instanceof ApiError)) return GENERIC;
  if (err.code && err.code !== 'invalid_request' && BY_CODE[err.code]) return BY_CODE[err.code];
  return err.detail || GENERIC;
}

/** "Made with Groq" for provider "groq"; null for a provider we don't know. */
export function providerLine(provider: string | null | undefined): string | null {
  if (provider === 'groq') return 'Made with Groq';
  if (provider === 'gemini') return 'Made with Gemini';
  return null;
}
